BAND_VARIANTS = [('default', 'Средняя резинка', 'Выбирай такую, чтобы последние 2–3 повторения шли тяжело, но чисто'),
                 ('light', 'Лёгкая резинка', 'Если техника страдает или не набираются повторения'),
                 ('heavy', 'Тяжёлая резинка', 'Когда средняя даётся на верхней границе повторений')]

def mk(key, name, pattern, prim, sec, comp, joint, equip, sets, reps, rest, cues, subs, steps, nuances, mistakes, focus, variants=None, pain=(), skill=1, unit='bodyweight', prog='rep_only', stab=1, rom='full'):
    return dict(key=key, name=name, movementPattern=pattern, primaryMuscles=prim, secondaryMuscles=sec, isCompound=comp,
        jointStress=joint, axialLoad=0, stabilityRequirement=stab, rangeOfMotion=rom,
        painSensitiveAreas=[dict(area=a, note=n) for a, n in pain], equipmentRequirements=equip, skillLevel=skill,
        progressionType=prog, loadUnit=unit, defaultSets=sets, defaultRepRange=dict(min=reps[0], max=reps[1]), defaultRestSec=rest,
        cues=cues, curatedSubstituteKeys=subs,
        variants=[dict(key=k, label=l, note=n) for k, l, n in (variants or [('default', 'Стандартный вариант', None)])],
        technique=dict(steps=steps, nuances=nuances, mistakes=mistakes, focus=focus))

def band(key, name, pattern, prim, sec, comp, joint, sets, reps, cues, subs, steps, nuances, mistakes, focus, pain=(), skill=1, equip=None, rest=60):
    return mk(key, name, pattern, prim, sec, comp, joint, equip or BAND, sets, reps, rest, cues, subs, steps,
              nuances + ['Сила резинки растёт к концу движения: вернись назад медленно, не давай ей «хлопнуть».'], mistakes, focus, variants=BAND_VARIANTS, pain=pain, skill=skill)

